{
  "format": "loops/0.1",
  "name": "conformance-edge",
  "version": "1.0.0",
  "inputs": {
    "schema": true
  },
  "steps": [
    {
      "id": "prefix",
      "kind": "code",
      "runtime": "python3",
      "file": "echo.py",
      "requires": [],
      "input": {
        "value": {
          "label": "P"
        }
      },
      "output": {
        "schema": true
      }
    },
    {
      "id": "produce",
      "kind": "infer",
      "requires": [],
      "instructions": "Return the next item as JSON.",
      "input": {
        "from": ""
      },
      "output": {
        "schema": {
          "type": "object",
          "properties": {
            "item": {
              "type": "string"
            }
          },
          "required": [
            "item"
          ],
          "additionalProperties": false
        }
      }
    },
    {
      "id": "judge",
      "kind": "code",
      "runtime": "python3",
      "file": "judge.py",
      "requires": [],
      "input": {
        "item": {
          "from": "/steps/produce/output/item"
        },
        "carry": {
          "from": "/carry"
        }
      },
      "output": {
        "schema": {
          "type": "object",
          "properties": {
            "ready": {
              "type": "boolean"
            },
            "note": {
              "type": "string"
            }
          },
          "required": [
            "ready",
            "note"
          ],
          "additionalProperties": false
        }
      }
    },
    {
      "id": "suffix",
      "kind": "code",
      "runtime": "python3",
      "file": "echo.py",
      "requires": [],
      "input": {
        "item": {
          "from": "/steps/produce/output/item"
        },
        "assessment": {
          "from": "/steps/judge/output"
        },
        "prefix": {
          "from": "/steps/prefix/output"
        }
      },
      "output": {
        "schema": true
      }
    }
  ],
  "output": {
    "from": "/steps/suffix/output"
  },
  "repeat": {
    "from": "produce",
    "through": "judge",
    "max_iterations": 3,
    "until": {
      "from": "/steps/judge/output/ready"
    },
    "carry": {
      "initial": {
        "prior": {
          "value": null
        },
        "note": {
          "value": ""
        }
      },
      "next": {
        "from": "/steps/produce/output/absent"
      }
    }
  }
}
